package ir.ghadmino.stepcounter\n\nimport android.Manifest\nimport android.content.Context\nimport android.content.Intent\nimport android.content.pm.PackageManager\nimport android.os.Build\nimport android.os.Bundle\nimport androidx.activity.ComponentActivity\nimport androidx.activity.compose.setContent\nimport androidx.activity.result.contract.ActivityResultContracts\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.rememberScrollState\nimport androidx.compose.foundation.verticalScroll\nimport androidx.compose.material.icons.Icons\nimport androidx.compose.material.icons.filled.BarChart\nimport androidx.compose.material.icons.filled.DirectionsWalk\nimport androidx.compose.material.icons.filled.LocalFireDepartment\nimport androidx.compose.material.icons.filled.Paid\nimport androidx.compose.material.icons.filled.Route\nimport androidx.compose.material.icons.filled.Settings\nimport androidx.compose.material.icons.filled.Speed\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.ui.Alignment\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.platform.LocalContext\nimport androidx.compose.ui.text.font.FontWeight\nimport androidx.compose.ui.unit.dp\nimport ir.ghadmino.stepcounter.reward.CoinWallet\nimport ir.ghadmino.stepcounter.reward.RewardCenter\nimport ir.ghadmino.stepcounter.speed.SpeedTracker\nimport ir.ghadmino.stepcounter.stats.StatsRepository\nimport ir.ghadmino.stepcounter.stats.StatsScreen\nimport ir.ghadmino.stepcounter.step.StepCounterService\nimport ir.ghadmino.stepcounter.step.StepHistory\nimport ir.ghadmino.stepcounter.ui.theme.GhadminoTheme\nimport kotlinx.coroutines.delay\n\nclass MainActivity : ComponentActivity() {\n    private lateinit var speedTracker: SpeedTracker\n    private val permissionLauncher = registerForActivityResult(ActivityResultContracts.RequestMultiplePermissions()) { speedTracker.start() }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        speedTracker = SpeedTracker(this)\n        requestPermissions()\n        setContent {\n            var themeId by remember { mutableStateOf(CoinWallet.selectedTheme(this@MainActivity)) }\n            GhadminoTheme(themeId = themeId) {\n                GhadminoApp(speedTracker) { newTheme ->\n                    CoinWallet.setSelectedTheme(this@MainActivity, newTheme)\n                    themeId = newTheme\n                }\n            }\n        }\n        startStepService()\n    }\n\n    override fun onResume() { super.onResume(); if (::speedTracker.isInitialized) speedTracker.start() }\n    override fun onPause() { if (::speedTracker.isInitialized) speedTracker.stop(); super.onPause() }\n\n    private fun requestPermissions() {\n        val permissions = mutableListOf<String>()\n        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q && checkSelfPermission(Manifest.permission.ACTIVITY_RECOGNITION) != PackageManager.PERMISSION_GRANTED) permissions.add(Manifest.permission.ACTIVITY_RECOGNITION)\n        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU && checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED) permissions.add(Manifest.permission.POST_NOTIFICATIONS)\n        if (checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION) != PackageManager.PERMISSION_GRANTED && checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION) != PackageManager.PERMISSION_GRANTED) {\n            permissions.add(Manifest.permission.ACCESS_FINE_LOCATION); permissions.add(Manifest.permission.ACCESS_COARSE_LOCATION)\n        }\n        if (permissions.isNotEmpty()) permissionLauncher.launch(permissions.toTypedArray())\n    }\n\n    private fun startStepService() {\n        val intent = Intent(this, StepCounterService::class.java)\n        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) startForegroundService(intent) else startService(intent)\n    }\n}\n\n@OptIn(ExperimentalMaterial3Api::class)\n@Composable\nfun GhadminoApp(speedTracker: SpeedTracker, onThemeChanged: (String) -> Unit) {\n    val context = LocalContext.current\n    val prefs = remember { context.getSharedPreferences("ghadmino_ui", Context.MODE_PRIVATE) }\n    var goal by remember { mutableIntStateOf(prefs.getInt("daily_goal", 8000)) }\n    var steps by remember { mutableIntStateOf(StepCounterService.todaySteps) }\n    var currentSpeed by remember { mutableFloatStateOf(speedTracker.currentSpeedKmh) }\n    var averageSpeed by remember { mutableFloatStateOf(speedTracker.averageSpeedKmh) }\n    var minimumSpeed by remember { mutableFloatStateOf(speedTracker.minimumSpeedKmh) }\n    var maximumSpeed by remember { mutableFloatStateOf(speedTracker.maximumSpeedKmh) }\n    var coins by remember { mutableIntStateOf(CoinWallet.balance(context)) }\n    var selectedTheme by remember { mutableStateOf(CoinWallet.selectedTheme(context)) }\n    var showStats by remember { mutableStateOf(false) }\n    var showRewards by remember { mutableStateOf(false) }\n    var showHistory by remember { mutableStateOf(false) }\n    var showGoalDialog by remember { mutableStateOf(false) }\n    var info by remember { mutableStateOf<String?>(null) }\n\n    LaunchedEffect(Unit) {\n        while (true) {\n            steps = StepCounterService.todaySteps\n            StepHistory.saveToday(context, steps)\n            CoinWallet.syncStepReward(context, steps)\n            if (steps >= goal) CoinWallet.claimGoalReward(context)\n            coins = CoinWallet.balance(context)\n            currentSpeed = speedTracker.currentSpeedKmh\n            averageSpeed = speedTracker.averageSpeedKmh\n            minimumSpeed = speedTracker.minimumSpeedKmh\n            maximumSpeed = speedTracker.maximumSpeedKmh\n            delay(1000)\n        }\n    }\n\n    val progress = if (goal > 0) (steps.toFloat() / goal).coerceIn(0f, 1f) else 0f\n    val distanceKm = steps * 0.00075\n    val calories = steps * 0.04\n\n    Scaffold(topBar = {\n        TopAppBar(\n            title = { Column { Text("قدم‌شمار قدمینو", fontWeight = FontWeight.Bold); Text("فعالیت امروز", style = MaterialTheme.typography.labelSmall) } },\n            actions = {\n                AssistChip(onClick = { showRewards = true }, label = { Text(coins.toString()) }, leadingIcon = { Icon(Icons.Default.Paid, null) })\n                IconButton(onClick = { showStats = true }) { Icon(Icons.Default.BarChart, "آمار") }\n                IconButton(onClick = { showHistory = true }) { Icon(Icons.Default.Route, "تاریخچه") }\n                IconButton(onClick = { showGoalDialog = true }) { Icon(Icons.Default.Settings, "تنظیمات") }\n            }\n        )\n    }) { padding ->\n        Column(Modifier.fillMaxSize().padding(padding).padding(16.dp).verticalScroll(rememberScrollState()), horizontalAlignment = Alignment.CenterHorizontally) {\n            Card(Modifier.fillMaxWidth(), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer)) {\n                Column(Modifier.padding(24.dp), horizontalAlignment = Alignment.CenterHorizontally) {\n                    Icon(Icons.Default.DirectionsWalk, null, Modifier.size(54.dp)); Spacer(Modifier.height(8.dp))\n                    Text(steps.toString(), style = MaterialTheme.typography.displayLarge, fontWeight = FontWeight.Bold)\n                    Text("قدم امروز", style = MaterialTheme.typography.titleMedium); Spacer(Modifier.height(16.dp))\n                    LinearProgressIndicator(progress = { progress }, Modifier.fillMaxWidth()); Spacer(Modifier.height(8.dp))\n                    Text((progress * 100).toInt().toString() + "٪ از هدف")\n                }\n            }\n            Spacer(Modifier.height(12.dp))\n            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {\n                StatCard(Modifier.weight(1f), { Icon(Icons.Default.Route, null) }, "مسافت", String.format("%.2f km", distanceKm))\n                StatCard(Modifier.weight(1f), { Icon(Icons.Default.LocalFireDepartment, null) }, "کالری", calories.toInt().toString() + " kcal")\n            }\n            Spacer(Modifier.height(12.dp)); SpeedCard(currentSpeed, averageSpeed, minimumSpeed, maximumSpeed); Spacer(Modifier.height(12.dp))\n            OutlinedButton(onClick = { showStats = true }, Modifier.fillMaxWidth()) { Icon(Icons.Default.BarChart, null); Spacer(Modifier.width(8.dp)); Text("آمار حرفه‌ای و نمودار ۳۰ روزه") }\n            Spacer(Modifier.height(8.dp))\n            Button(onClick = { showRewards = true }, Modifier.fillMaxWidth()) { Icon(Icons.Default.Paid, null); Spacer(Modifier.width(8.dp)); Text("مرکز جایزه و فروشگاه سکه") }\n            Spacer(Modifier.height(12.dp))\n            Card(Modifier.fillMaxWidth()) {\n                Column(Modifier.padding(18.dp)) {\n                    Text("هدف روزانه", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)\n                    Text(goal.toString() + " قدم", style = MaterialTheme.typography.titleLarge)\n                    Slider(value = goal.toFloat(), onValueChange = { goal = it.toInt(); prefs.edit().putInt("daily_goal", goal).apply() }, valueRange = 1000f..30000f, steps = 28)\n                }\n            }\n            Spacer(Modifier.height(12.dp))\n            Card(Modifier.fillMaxWidth(), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant)) {\n                Column(Modifier.padding(18.dp)) {\n                    Text("وضعیت قدم‌شمار", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold); Spacer(Modifier.height(8.dp))\n                    Text(if (StepCounterService.sensorAvailable) "✓ حسگر قدم‌شمار فعال است" else "⚠ حسگر قدم‌شمار روی این گوشی پیدا نشد")\n                    Text("شمارش قدم‌ها در پس‌زمینه ادامه پیدا می‌کند.")\n                }\n            }\n            Spacer(Modifier.height(16.dp))\n            Text("هر ۱۰۰۰ قدم = ۵ سکه • هدف روزانه = ۲۰ سکه", style = MaterialTheme.typography.labelMedium)\n            Text("سکه‌ها را برای تم‌ها و امکانات ویژه ذخیره کن.", style = MaterialTheme.typography.labelMedium)\n            Text("قدمینو • نسخه 1.2.0", style = MaterialTheme.typography.labelSmall)\n        }\n    }\n\n    if (showStats) AlertDialog(onDismissRequest = { showStats = false }, title = { Text("آمار حرفه‌ای") }, text = { StatsScreen(StatsRepository.load(context, goal), goal) }, confirmButton = { Button(onClick = { showStats = false }) { Text("بستن") } })\n\n    if (showRewards) AlertDialog(\n        onDismissRequest = { showRewards = false },\n        title = { Text("مرکز جایزه و فروشگاه") },\n        text = {\n            RewardCenter(\n                coins = coins, adAvailable = false, selectedTheme = selectedTheme,\n                onWatchAd = { info = "اتصال تبلیغ جایزه‌ای در مرحله تبلیغات انجام می‌شود؛ سکه فقط پس از تکمیل واقعی تبلیغ ثبت خواهد شد." },\n                onBuyFreeze = {\n                    info = if (CoinWallet.unlock(context, "streak_freeze", 250)) "محافظ زنجیره خریداری شد." else "سکه کافی نیست."\n                    coins = CoinWallet.balance(context)\n                },\n                onBuyTheme = { id, cost ->\n                    if (cost == 0) {\n                        CoinWallet.setSelectedTheme(context, id); selectedTheme = id; onThemeChanged(id)\n                        info = "تم فعال شد."\n                    } else if (CoinWallet.unlock(context, "theme_" + id, cost)) {\n                        CoinWallet.setSelectedTheme(context, id); selectedTheme = id; onThemeChanged(id)\n                        coins = CoinWallet.balance(context); info = "تم خریداری و فعال شد."\n                    } else {\n                        info = "سکه کافی نیست. با قدم‌زدن، هدف روزانه و بعداً تبلیغات جایزه‌ای سکه بگیر."\n                    }\n                }\n            )\n        },\n        confirmButton = { Button(onClick = { showRewards = false }) { Text("بستن") } }\n    )\n\n    if (showHistory) AlertDialog(onDismissRequest = { showHistory = false }, title = { Text("۷ روز اخیر") }, text = { Column { StepHistory.recent(context).forEach { Text(it.first + "   " + it.second + " قدم", Modifier.padding(vertical = 5.dp)) } } }, confirmButton = { Button(onClick = { showHistory = false }) { Text("بستن") } })\n\n    if (showGoalDialog) AlertDialog(onDismissRequest = { showGoalDialog = false }, title = { Text("تنظیم هدف") }, text = { Column { Text("هدف فعلی: " + goal + " قدم"); Slider(value = goal.toFloat(), onValueChange = { goal = it.toInt(); prefs.edit().putInt("daily_goal", goal).apply() }, valueRange = 1000f..30000f, steps = 28) } }, confirmButton = { Button(onClick = { showGoalDialog = false }) { Text("ذخیره") } })\n\n    info?.let { text -> LaunchedEffect(text) { delay(2500); info = null } }\n}\n\n@Composable\nfun SpeedCard(current: Float, average: Float, minimum: Float, maximum: Float) {\n    Card(Modifier.fillMaxWidth()) {\n        Column(Modifier.padding(18.dp)) {\n            Row(verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.Speed, null, Modifier.size(30.dp)); Spacer(Modifier.size(10.dp)); Text("سرعت حرکت", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold) }\n            Spacer(Modifier.height(14.dp)); Text("سرعت فعلی"); Text(String.format("%.1f km/h", current), style = MaterialTheme.typography.headlineMedium, fontWeight = FontWeight.Bold)\n            Spacer(Modifier.height(14.dp)); Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) { SpeedValue("میانگین", average); SpeedValue("کمترین", minimum); SpeedValue("بیشترین", maximum) }\n        }\n    }\n}\n\n@Composable fun SpeedValue(title: String, value: Float) { Column(horizontalAlignment = Alignment.CenterHorizontally) { Text(title, style = MaterialTheme.typography.labelMedium); Text(String.format("%.1f", value), fontWeight = FontWeight.Bold); Text("km/h", style = MaterialTheme.typography.labelSmall) } }\n\n@Composable fun StatCard(modifier: Modifier, icon: @Composable () -> Unit, title: String, value: String) { Card(modifier) { Column(Modifier.padding(16.dp)) { icon(); Spacer(Modifier.height(8.dp)); Text(title, style = MaterialTheme.typography.labelMedium); Text(value, fontWeight = FontWeight.Bold) } } }